{
    "level": "A1",
    "intro": "Ця сторінка збирає в одному місці <strong>основні граматичні патерни курсу English Sentence Builder A1</strong>, щоб перед фінальним уроком ти міг швидко повторити вже знайомі структури.",
    "rules": [
        {
            "label": "CORE FORMS",
            "color": "blue",
            "text": "Повтори <strong>to be, there is / there are, have got, can, Present Simple, Present Continuous, Past Simple, Future Simple</strong>.",
            "example": "She is happy. / There are books on the table. / I will come tomorrow."
        },
        {
            "label": "QUANTIFIERS",
            "color": "emerald",
            "text": "Зверни увагу на <strong>articles, some / any, much / many / a lot of</strong>.",
            "example": "It is an apple. / We do not have any apples. / There are a lot of books here."
        },
        {
            "label": "COMPARISON",
            "color": "rose",
            "text": "На фінальному етапі важливо не плутати <strong>comparatives</strong> і <strong>superlatives</strong>.",
            "example": "This house is bigger than that house. / This car is the most expensive."
        }
    ]
}

{
    "title": "2. Контрольний список перед уроком 16",
    "intro": "Швидка самоперевірка перед фінальним міксом тем:",
    "items": [
        {
            "label": "Перевірка 1",
            "title": "Article або no article?",
            "subtitle": "a / an / the мають відповідати іменнику та контексту."
        },
        {
            "label": "Перевірка 2",
            "title": "Some чи any?",
            "subtitle": "some у ствердженнях, any у питаннях і запереченнях у межах A1 drill."
        },
        {
            "label": "Перевірка 3",
            "title": "Much, many чи a lot of?",
            "subtitle": "Не плутай plural countable nouns та uncountable nouns."
        },
        {
            "label": "Перевірка 4",
            "title": "Comparative чи superlative?",
            "subtitle": "than = comparative; the / the most = superlative."
        }
    ]
}

{
    "title": "Пов'язані сторінки для швидкого повторення",
    "items": [
        {
            "label": "Verb to be — Present",
            "current": false
        },
        {
            "label": "There is / There are",
            "current": false
        },
        {
            "label": "Some / Any — Things",
            "current": false
        },
        {
            "label": "Comparative vs Superlative",
            "current": false
        },
        {
            "label": "A1 Mixed Revision",
            "current": true
        }
    ]
}

{
    "level": "A2",
    "intro": "Ця сторінка збирає в одному місці <strong>основні граматичні патерни курсу English Sentence Builder A2</strong>, щоб перед фінальним уроком ти міг швидко повторити вже знайомі структури.",
    "rules": [
        {
            "label": "TIME AND EXPERIENCE",
            "color": "blue",
            "text": "Повтори <strong>Present Perfect</strong>, контраст із <strong>Past Simple</strong> та типові time expressions.",
            "example": "I have just finished the report. / She visited Paris in 2022."
        },
        {
            "label": "PATTERNS AND LINKS",
            "color": "emerald",
            "text": "Зверни увагу на <strong>gerund vs infinitive, relative clauses, passive voice, reported speech</strong>.",
            "example": "She decided to learn Spanish. / This is the woman who works with my brother. / She said that she was tired."
        },
        {
            "label": "CONDITIONS AND REVIEW",
            "color": "rose",
            "text": "Перед фінальним drill важливо не плутати <strong>first conditional, second conditional, used to, question tags, be going to, should, have to</strong>.",
            "example": "We will go to the beach if it is sunny. / I would buy this house if I had more money. / You are not ready, are you?"
        }
    ]
}

{
    "title": "2. Контрольний список перед уроком 16",
    "intro": "Швидка самоперевірка перед фінальним міксом тем:",
    "items": [
        {
            "label": "Перевірка 1",
            "title": "Time marker чи open time?",
            "subtitle": "Не плутай Present Perfect з Past Simple, коли є finished time marker."
        },
        {
            "label": "Перевірка 2",
            "title": "If + present чи if + past?",
            "subtitle": "First Conditional і Second Conditional мають різні значення та форми."
        },
        {
            "label": "Перевірка 3",
            "title": "Infinitive чи gerund?",
            "subtitle": "Після mind, enjoy, decide та інших базових дієслів тримай правильний pattern."
        },
        {
            "label": "Перевірка 4",
            "title": "Auxiliary у question tag",
            "subtitle": "Tag має повторювати correct auxiliary і correct pronoun."
        }
    ]
}

{
    "title": "Пов'язані сторінки для швидкого повторення",
    "items": [
        {
            "label": "Present Perfect Forms",
            "current": false
        },
        {
            "label": "First Conditional",
            "current": false
        },
        {
            "label": "Reported Statements",
            "current": false
        },
        {
            "label": "Second Conditional",
            "current": false
        },
        {
            "label": "A2 Mixed Revision",
            "current": true
        }
    ]
}
